public final class ExtBoolArray {

    /**
     * Zahl die uebriggebliebenen False-Werte.
     *
     * @return Anzahl der False-Werte.
     */
    public int left() {
        int result = 0;
        for (int i = 0; i < werte.length; i++) {
            if (!werte[i]) {
                result++;
            }
        }
        return result;
    }
}

